namespace Customize\Repository;

use Doctrine\Persistence\ManagerRegistry as RegistryInterface;
use Eccube\Entity\ProductTag;
use Customize\Entity\Shop;
use Eccube\Entity\Master\ProductStatus;
/**
 * ProductTagRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class ProductTagRepository extends \Eccube\Repository\ProductTagRepository
{
    public function __construct(RegistryInterface $registry)
    {
        parent::__construct($registry);
    }


    public function getTagByShop(?Shop $Shop=null): array
    {

        //$ProsuctStatus = $this->getEntityManager()->getRepository(ProductStatus::class)->find(ProductStatus::DISPLAY_SHOW);


        $qb = $this->createQueryBuilder('pt')
                //   ->select('tg') 
                   ->innerJoin('pt.Product', 'p')
                   ->innerJoin('pt.Tag','tg')
                   ->orderBy('tg.sort_no', 'DESC')
                   ->where('p.Status = :ProductStatus')
                   ->setParameter('ProductStatus',ProductStatus::DISPLAY_SHOW);
                   if($Shop){
                        $qb->andWhere('p.Shop = :Shop')
                        ->setParameter('Shop',$Shop);
                   }
                 //  ->groupBy('tg');

        $PTs= $qb->getQuery()->getResult();

        $Re =[];
        foreach ($PTs as $PT){
                $Re[$PT->getTag()->getId()]  = $PT->getTag();
            }

        return $Re ;     

    }

 }
